import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

class BasicPrefsExample extends StatefulWidget {
  const BasicPrefsExample({super.key});

  @override
  State<BasicPrefsExample> createState() => _BasicPrefsExampleState();
}

class _BasicPrefsExampleState extends State<BasicPrefsExample> {
  // SharedPreferences 인스턴스를 저장할 변수
  SharedPreferences? _prefs;

  // 저장된 값들
  String _username = '';
  int _counter = 0;
  bool _isDarkMode = false;

  @override
  void initState() {
    super.initState();
    _loadPreferences(); // 앱 시작 시 저장된 값 불러오기
  }

  // 저장된 데이터 불러오기
  Future<void> _loadPreferences() async {
    // getInstance()는 비동기 - 최초 한 번만 호출하면 됨
    _prefs = await SharedPreferences.getInstance();

    setState(() {
      // 저장된 값이 없으면 기본값 사용
      _username = _prefs?.getString('username') ?? '게스트';
      _counter = _prefs?.getInt('counter') ?? 0;
      _isDarkMode = _prefs?.getBool('isDarkMode') ?? false;
    });
  }

  // 사용자명 저장
  Future<void> _saveUsername(String name) async {
    await _prefs?.setString('username', name);
    setState(() => _username = name);
  }

  // 카운터 증가 및 저장
  Future<void> _incrementCounter() async {
    final newValue = _counter + 1;
    await _prefs?.setInt('counter', newValue);
    setState(() => _counter = newValue);
  }

  // 다크모드 토글 및 저장
  Future<void> _toggleDarkMode() async {
    final newValue = !_isDarkMode;
    await _prefs?.setBool('isDarkMode', newValue);
    setState(() => _isDarkMode = newValue);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('SharedPreferences 기본')),
      body: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text('사용자: $_username', style: const TextStyle(fontSize: 18)),
            const SizedBox(height: 8),
            Text('카운터: $_counter', style: const TextStyle(fontSize: 18)),
            const SizedBox(height: 8),
            Text('다크모드: ${_isDarkMode ? "ON" : "OFF"}'),
            const SizedBox(height: 24),
            ElevatedButton(
              onPressed: _incrementCounter,
              child: const Text('카운터 +1'),
            ),
            const SizedBox(height: 8),
            ElevatedButton(
              onPressed: _toggleDarkMode,
              child: const Text('다크모드 토글'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:shared_preferences/shared_preferences.dart';

class PrefsService {
  static SharedPreferences? _prefs;

  // 싱글톤 패턴으로 인스턴스 관리
  static Future<void> init() async {
    _prefs = await SharedPreferences.getInstance();
  }

  // ===== String 타입 =====
  // 사용처: 사용자명, 토큰, 선택된 언어 코드 등
  static Future<void> setUsername(String value) async {
    await _prefs?.setString('username', value);
  }
  static String getUsername() => _prefs?.getString('username') ?? 'Guest';

  // ===== int 타입 =====
  // 사용처: 카운터, 마지막 접속 시간(timestamp), 레벨 등
  static Future<void> setLastVisit(int timestamp) async {
    await _prefs?.setInt('lastVisit', timestamp);
  }
  static int getLastVisit() => _prefs?.getInt('lastVisit') ?? 0;

  // ===== bool 타입 =====
  // 사용처: 다크모드, 알림 설정, 온보딩 완료 여부 등
  static Future<void> setDarkMode(bool value) async {
    await _prefs?.setBool('darkMode', value);
  }
  static bool isDarkMode() => _prefs?.getBool('darkMode') ?? false;

  // ===== double 타입 =====
  // 사용처: 폰트 크기, 볼륨, 마지막 스크롤 위치 등
  static Future<void> setFontSize(double value) async {
    await _prefs?.setDouble('fontSize', value);
  }
  static double getFontSize() => _prefs?.getDouble('fontSize') ?? 14.0;

  // ===== List<String> 타입 =====
  // 사용처: 최근 검색어, 즐겨찾기 ID 목록, 태그 등
  static Future<void> setRecentSearches(List<String> value) async {
    await _prefs?.setStringList('recentSearches', value);
  }
  static List<String> getRecentSearches() {
    return _prefs?.getStringList('recentSearches') ?? [];
  }

  // ===== 특정 키 삭제 =====
  static Future<void> removeKey(String key) async {
    await _prefs?.remove(key);
  }

  // ===== 모든 데이터 삭제 (로그아웃 시 활용) =====
  static Future<void> clearAll() async {
    await _prefs?.clear();
  }

  // ===== 키 존재 여부 확인 =====
  static bool hasKey(String key) {
    return _prefs?.containsKey(key) ?? false;
  }

  // ===== 저장된 모든 키 조회 =====
  static Set<String> getAllKeys() {
    return _prefs?.getKeys() ?? {};
  }
}

// main.dart에서 초기화
void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await PrefsService.init(); // 앱 시작 시 한 번만 호출
  runApp(const MyApp());
}

import 'dart:convert';
import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

// 앱 설정을 담는 불변 클래스
class AppSettings {
  final ThemeMode themeMode;
  final String languageCode;
  final double fontSize;
  final bool notificationsEnabled;
  final bool onboardingCompleted;

  const AppSettings({
    this.themeMode = ThemeMode.system,
    this.languageCode = 'ko',
    this.fontSize = 14.0,
    this.notificationsEnabled = true,
    this.onboardingCompleted = false,
  });

  // copyWith 패턴으로 불변성 유지
  AppSettings copyWith({
    ThemeMode? themeMode,
    String? languageCode,
    double? fontSize,
    bool? notificationsEnabled,
    bool? onboardingCompleted,
  }) {
    return AppSettings(
      themeMode: themeMode ?? this.themeMode,
      languageCode: languageCode ?? this.languageCode,
      fontSize: fontSize ?? this.fontSize,
      notificationsEnabled: notificationsEnabled ?? this.notificationsEnabled,
      onboardingCompleted: onboardingCompleted ?? this.onboardingCompleted,
    );
  }

  // JSON 직렬화
  Map<String, dynamic> toJson() => {
    'themeMode': themeMode.index,
    'languageCode': languageCode,
    'fontSize': fontSize,
    'notificationsEnabled': notificationsEnabled,
    'onboardingCompleted': onboardingCompleted,
  };

  factory AppSettings.fromJson(Map<String, dynamic> json) {
    return AppSettings(
      themeMode: ThemeMode.values[json['themeMode'] ?? 0],
      languageCode: json['languageCode'] ?? 'ko',
      fontSize: (json['fontSize'] ?? 14.0).toDouble(),
      notificationsEnabled: json['notificationsEnabled'] ?? true,
      onboardingCompleted: json['onboardingCompleted'] ?? false,
    );
  }
}

// 설정 관리 서비스
class SettingsService extends ChangeNotifier {
  static const _settingsKey = 'app_settings';

  late SharedPreferences _prefs;
  AppSettings _settings = const AppSettings();

  AppSettings get settings => _settings;

  // 초기화 (앱 시작 시 호출)
  Future<void> init() async {
    _prefs = await SharedPreferences.getInstance();
    await _loadSettings();
  }

  // 저장된 설정 불러오기
  Future<void> _loadSettings() async {
    final jsonString = _prefs.getString(_settingsKey);
    if (jsonString != null) {
      try {
        final json = jsonDecode(jsonString) as Map<String, dynamic>;
        _settings = AppSettings.fromJson(json);
      } catch (e) {
        // 파싱 실패 시 기본값 사용
        _settings = const AppSettings();
      }
    }
    notifyListeners();
  }

  // 설정 저장
  Future<void> _saveSettings() async {
    final jsonString = jsonEncode(_settings.toJson());
    await _prefs.setString(_settingsKey, jsonString);
    notifyListeners();
  }

  // 개별 설정 업데이트 메서드들
  Future<void> setThemeMode(ThemeMode mode) async {
    _settings = _settings.copyWith(themeMode: mode);
    await _saveSettings();
  }

  Future<void> setLanguage(String code) async {
    _settings = _settings.copyWith(languageCode: code);
    await _saveSettings();
  }

  Future<void> setFontSize(double size) async {
    _settings = _settings.copyWith(fontSize: size);
    await _saveSettings();
  }

  Future<void> setNotifications(bool enabled) async {
    _settings = _settings.copyWith(notificationsEnabled: enabled);
    await _saveSettings();
  }

  Future<void> completeOnboarding() async {
    _settings = _settings.copyWith(onboardingCompleted: true);
    await _saveSettings();
  }

  // 설정 초기화
  Future<void> resetSettings() async {
    _settings = const AppSettings();
    await _prefs.remove(_settingsKey);
    notifyListeners();
  }
}

import 'package:shared_preferences/shared_preferences.dart';

/// SharedPreferencesWithCache를 활용한 고성능 설정 서비스
/// 
/// 장점:
/// - 지정한 키들을 메모리에 캐싱하여 동기적으로 빠르게 읽기 가능
/// - 쓰기는 여전히 비동기로 안전하게 처리
/// - allowList로 관리할 키를 명시적으로 지정
class CachedPrefsService {
  static SharedPreferencesWithCache? _prefs;

  // 캐싱할 키 목록 정의
  static const _cachedKeys = {
    'theme',
    'language', 
    'fontSize',
    'notifications',
    'onboardingDone',
  };

  /// 초기화 - 앱 시작 시 반드시 호출
  static Future<void> init() async {
    _prefs = await SharedPreferencesWithCache.create(
      cacheOptions: SharedPreferencesWithCacheOptions(
        // 이 키들만 메모리에 캐싱됨
        allowList: _cachedKeys,
      ),
    );
  }

  /// 테마 설정 (동기 읽기 가능!)
  static String get theme => _prefs?.getString('theme') ?? 'system';

  static Future<void> setTheme(String value) async {
    await _prefs?.setString('theme', value);
  }

  /// 언어 설정
  static String get language => _prefs?.getString('language') ?? 'ko';

  static Future<void> setLanguage(String value) async {
    await _prefs?.setString('language', value);
  }

  /// 폰트 크기
  static double get fontSize => _prefs?.getDouble('fontSize') ?? 14.0;

  static Future<void> setFontSize(double value) async {
    await _prefs?.setDouble('fontSize', value);
  }

  /// 알림 설정
  static bool get notifications => _prefs?.getBool('notifications') ?? true;

  static Future<void> setNotifications(bool value) async {
    await _prefs?.setBool('notifications', value);
  }

  /// 온보딩 완료 여부
  static bool get onboardingDone => _prefs?.getBool('onboardingDone') ?? false;

  static Future<void> setOnboardingDone(bool value) async {
    await _prefs?.setBool('onboardingDone', value);
  }

  /// 캐시 새로고침 (다른 곳에서 값이 변경되었을 때)
  static Future<void> reloadCache() async {
    await _prefs?.reloadCache();
  }
}

// 사용 예시
void main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await CachedPrefsService.init();

  // 동기적으로 바로 읽기 가능! (await 불필요)
  final theme = CachedPrefsService.theme;
  final language = CachedPrefsService.language;

  print('현재 테마: $theme, 언어: $language');

  runApp(const MyApp());
}

